// src/world/maps/builtEnvironmentRecords.ts — what each battlefield's built environment looks like in its real place and
// year, and the photographs that show it (item built-env-270; the rows the game reads are builtEnvironmentTable.ts). One
// record per battlefield, typed over MapId. Each photograph is a Wikimedia Commons file (or a NASA public-domain frame)
// with its author and licence as Commons gives them; the summaries are what the photos show of the roads, the kerbs and
// pavements, the paths and alleys, the squares and courtyards, and the shore, with colours read off them (sRGB).
// Only the receipts and the tools load this file (the prose and the credits would otherwise ride in every world worker).
import type { MapId } from './mapIds.ts';

export interface BuiltEnvironmentPhoto {
  readonly url: string;
  readonly author: string;
  readonly license: string;
  readonly shows: string;
}

export interface BuiltEnvironmentRecord {
  readonly setting: string;
  readonly photos: readonly BuiltEnvironmentPhoto[];
  readonly roads: string;
  readonly kerbsPavements: string;
  readonly pathsAlleys: string;
  readonly squaresCourtyards: string;
  readonly shore: string;
  readonly notes: string;
}

